use serde_json::Value;
use std::path::PathBuf;
use std::{
    collections::HashMap,
    sync::{atomic::AtomicU64, Arc},
    time::Instant,
};

#[derive(Clone)]
pub struct BoundedQueryCursor {
    pub query_hash: String,
    pub principal_key_id: String,
    pub namespace: String,
    pub records: Arc<Vec<Value>>,
    pub position: usize,
    pub created_at: u64,
}

use crate::{
    application_contract::ApplicationContractStore, artifacts::ArtifactStore, audit::AuditLog,
    auth::KeyStore, canonical_principals::CanonicalPrincipalAuthority,
    causal::CanonicalEventAuthority,
    clock::LeaseClock, cluster::ClusterStore,
    connections::ConnectionStore, content::ContentStore, identity::IdentityStore,
    leases::LeaseStore, metrics::Metrics, portable_bundle::BundleStore,
    providers::ProviderStore, releases::ReleaseStore, sessions::SessionVerifier,
    tenancy::TenancyStore,
};
use feltdb::{
    application::ApplicationStore,
    application_runtime::RuntimeStore,
    authorization::{GrantSigner, GrantStore},
    sync_contract::SyncStore,
    worker_mesh::WorkerMeshStore,
    workload::WorkloadStore,
    FeltDb, StateTriggerStore,
};

#[derive(Clone)]
pub struct AppState {
    pub started_at: Instant,
    pub db: FeltDb,
    pub namespace: Arc<str>,
    pub ids: Arc<AtomicU64>,
    pub auth_enabled: bool,
    pub authentication_workers: Arc<tokio::sync::Semaphore>,
    pub keys: KeyStore,
    pub metrics: Metrics,
    pub cluster: ClusterStore,
    pub audit: AuditLog,
    pub peer_client: reqwest::Client,
    pub peer_token: Option<Arc<str>>,
    pub lifecycle_lock: Arc<tokio::sync::Mutex<()>>,
    /// Bounds concurrent schema snapshots before canonical commit admission.
    ///
    /// State-contract transactions inspect a full authority snapshot before
    /// entering the database's atomic commit. Keeping that interval exclusive
    /// prevents an unbounded request burst from retaining one snapshot per
    /// request. The database's guarded transaction remains the atomic commit
    /// arbiter; this semaphore only bounds pre-commit working memory.
    pub state_transaction_admission: Arc<tokio::sync::Semaphore>,
    pub worker_enabled: bool,
    pub leases: LeaseStore,
    pub content: ContentStore,
    pub artifacts: ArtifactStore,
    pub bundles: BundleStore,
    pub releases: ReleaseStore,
    pub events: CanonicalEventAuthority,
    pub providers: ProviderStore,
    pub contracts: ApplicationContractStore,
    pub advertise_url: Option<Arc<str>>,
    pub lease_clock: LeaseClock,
    pub backup_barrier: Arc<tokio::sync::RwLock<()>>,
    pub backup_artifacts: Arc<Vec<(String, PathBuf)>>,
    pub tenancy: TenancyStore,
    pub sessions: SessionVerifier,
    pub principals: CanonicalPrincipalAuthority,
    pub connections: ConnectionStore,
    pub identities: IdentityStore,
    pub applications: ApplicationStore,
    pub runtimes: RuntimeStore,
    pub grant_signer: GrantSigner,
    pub grants: Arc<std::sync::Mutex<GrantStore>>,
    pub sync: Arc<std::sync::Mutex<SyncStore>>,
    pub workloads: Arc<std::sync::Mutex<WorkloadStore>>,
    pub state_triggers: Arc<std::sync::Mutex<StateTriggerStore>>,
    pub mesh: Arc<std::sync::Mutex<WorkerMeshStore>>,
    pub readiness_probe: Arc<PathBuf>,
    pub bounded_query_cursors: Arc<std::sync::Mutex<HashMap<String, BoundedQueryCursor>>>,
    /// Bounds how many requests may be in flight at once.
    ///
    /// Every read and write serializes on one lock inside the database, so
    /// admitting unbounded concurrency does not increase throughput — it only
    /// converts a queue the server could reject quickly into one it holds until
    /// clients give up. Shedding at the door turns a pile-up into a fast 503
    /// with `Retry-After`.
    pub admission: Arc<tokio::sync::Semaphore>,
    /// How long a request may take before the server abandons it.
    ///
    /// Without this a slow operation runs until the *client* times out, and the
    /// work keeps running after the client has gone.
    pub request_deadline: std::time::Duration,
}
